(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ExamEngine=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const choices=e=>e.choices||['A','B','C','D'];
const count=e=>e.answers.length;
function validate(exams){if(!Array.isArray(exams)||!exams.length)throw Error('EXAMES-QUANTIDADE');const ids=new Set();for(const e of exams){const concurso=e?.kind==='concurso',allowed=choices(e),host=concurso?'conhecimento.fgv.br':'s.oab.org.br';if(!e||ids.has(e.id)||!Number.isInteger(e.number)||e.type!==1||e.keyStatus!=='definitivo'||!Array.isArray(e.answers)||![80,100].includes(e.answers.length)||(!concurso&&e.answers.length!==80)||!e.answers.every(v=>[...allowed,'*'].includes(v))||allowed.join('')!==(concurso?'ABCDE':'ABCD')||![e.paperUrl,e.keyUrl].every(u=>typeof u==='string'&&u.startsWith(`https://${host}/`))||!Number.isInteger(e.durationMinutes)||e.durationMinutes<=0||(!concurso&&(e.passScore!==40||e.durationMinutes!==300))||(concurso&&(e.passScore!==null||!e.title||!e.career)))throw Error('EXAMES-INVALIDOS');ids.add(e.id);}return exams;}
function fresh(exam,timed,now=Date.now()){return {examId:exam.id,version:exam.version,answers:Array(count(exam)).fill(null),position:0,startedAt:now,deadline:timed?now+exam.durationMinutes*60000:null,finishedAt:null};}
function validDraft(d,e){return !!d&&d.examId===e.id&&d.version===e.version&&Array.isArray(d.answers)&&d.answers.length===count(e)&&d.answers.every(v=>v===null||choices(e).includes(v))&&Number.isInteger(d.position)&&d.position>=0&&d.position<count(e)&&Number.isFinite(d.startedAt)&&d.startedAt>0&&(d.deadline===null||(Number.isFinite(d.deadline)&&d.deadline===d.startedAt+e.durationMinutes*60000))&&(d.finishedAt===null||(Number.isFinite(d.finishedAt)&&d.finishedAt>=d.startedAt));}
function grade(exam,answers){if(!Array.isArray(answers)||answers.length!==count(exam)||!answers.every(v=>v===null||choices(exam).includes(v)))throw Error('RESPOSTAS-INVALIDAS');let correct=0,annulled=0,wrong=0,blank=0;const details=exam.answers.map((key,i)=>{const value=answers[i];let status;if(key==='*'){annulled++;status='annulled';}else if(value===null){blank++;status='blank';}else if(value===key){correct++;status='correct';}else{wrong++;status='wrong';}return {number:i+1,answer:value,key,status};});const score=correct+annulled;return {correct,annulled,wrong,blank,score,passed:exam.passScore===null?null:score>=exam.passScore,details};}
function expired(d,now=Date.now()){return !d.finishedAt&&d.deadline!==null&&now>=d.deadline;}
return {validate,fresh,validDraft,grade,expired,choices,count};
});
